const parallaxScript = String.raw`<script>
(function(){
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var els = Array.prototype.slice.call(document.querySelectorAll('[data-parallax]'));
  if (!els.length) return;
  var ticking = false;
  function update(){
    var y = window.scrollY || 0;
    els.forEach(function(el){
      var speed = parseFloat(el.getAttribute('data-parallax')) || 0;
      el.style.transform = 'translate3d(0,' + (y * speed) + 'px,0)';
    });
    ticking = false;
  }
  window.addEventListener('scroll', function(){if(!ticking){window.requestAnimationFrame(update);ticking=true;}},{passive:true});
  update();
})();
</script>`;

function shell(title, body, description = "Preview de cases do portfólio Studio Y") {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="${description}"><title>${title}</title><style>${css}</style></head><body>${body}${parallaxScript}</body></html>`;
}

function topNav(extra = "") {
  return `<nav class="site-nav"><div class="wrap nav-inner"><a class="brand" href="/">Mariana Yoshino</a><div class="nav-links">${extra}<span class="preview-pill">Preview · cases técnicos</span></div></div></nav>`;
}

