const finalCaseHeroJs = "(() => {\n  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const clamp = (value, min, max) => Math.min(Math.max(value, min), max);\n\n  document.querySelectorAll('[data-parallax]').forEach((hero) => {\n    const layers = [...hero.querySelectorAll('[data-depth]')];\n    const playButton = hero.querySelector('.hero-play');\n    const featureTags = [...hero.querySelectorAll('.feature-tag')];\n\n    const setPlaying = (playing) => {\n      hero.classList.toggle('is-playing', playing && !reducedMotion);\n      if (!playButton) return;\n      playButton.setAttribute('aria-pressed', String(playing));\n      playButton.querySelector('.play-icon').textContent = playing ? 'Ⅱ' : '▶';\n      playButton.querySelector('.play-label').textContent = playing ? 'Pausar movimento' : 'Ativar movimento';\n    };\n\n    if (playButton) playButton.addEventListener('click', () => setPlaying(!hero.classList.contains('is-playing')));\n    if (hero.hasAttribute('data-autoplay')) setPlaying(true);\n\n    if (!reducedMotion) {\n      requestAnimationFrame(() => {\n        hero.classList.add('motion-ready');\n        window.setTimeout(() => hero.classList.add('motion-settled'), 1600);\n      });\n\n      hero.addEventListener('pointermove', (event) => {\n        if (!hero.classList.contains('is-playing')) return;\n        const box = hero.getBoundingClientRect();\n        const x = (event.clientX - box.left) / box.width - .5;\n        const y = (event.clientY - box.top) / box.height - .5;\n        hero.style.setProperty('--tilt-x', `${y * -5}deg`);\n        hero.style.setProperty('--tilt-y', `${x * 7}deg`);\n        hero.style.setProperty('--light-x', `${(x + .5) * 100}%`);\n        hero.style.setProperty('--light-y', `${(y + .5) * 100}%`);\n        layers.forEach((layer) => {\n          const depth = Number(layer.dataset.depth || 0);\n          layer.style.setProperty('--px', `${x * depth * 120}px`);\n          layer.style.setProperty('--py', `${y * depth * 90}px`);\n        });\n      });\n      hero.addEventListener('pointerleave', () => layers.forEach((layer) => {\n        layer.style.setProperty('--px', '0px');\n        layer.style.setProperty('--py', '0px');\n        hero.style.setProperty('--tilt-x', '0deg');\n        hero.style.setProperty('--tilt-y', '0deg');\n      }));\n\n      let ticking = false;\n      const updateScrollMotion = () => {\n        const box = hero.getBoundingClientRect();\n        const progress = clamp(-box.top / Math.max(box.height, 1), 0, 1);\n        hero.style.setProperty('--scroll-copy', `${progress * -72}px`);\n        hero.style.setProperty('--scroll-visual', `${progress * 118}px`);\n        hero.style.setProperty('--hero-scale', String(1 - progress * .08));\n        hero.style.setProperty('--hero-fade', String(1 - progress * .48));\n        ticking = false;\n      };\n      const requestScrollMotion = () => {\n        if (ticking) return;\n        ticking = true;\n        requestAnimationFrame(updateScrollMotion);\n      };\n      updateScrollMotion();\n      window.addEventListener('scroll', requestScrollMotion, { passive: true });\n\n      if (featureTags.length) {\n        let activeTag = 0;\n        featureTags[0].classList.add('is-active');\n        window.setInterval(() => {\n          featureTags[activeTag].classList.remove('is-active');\n          activeTag = (activeTag + 1) % featureTags.length;\n          featureTags[activeTag].classList.add('is-active');\n        }, 1800);\n      }\n    }\n  });\n})();\n";
